        return make_decorator(deco)
    elif has_1pos_and_kwonly(deco):
        # Function with 1 positional arg + optional keyword-only args
        return make_decorator_kwonly(deco)
    else:
        # Any arguments after first become decorator arguments
        # And a decorator with arguments is essentialy a decorator fab
        def decorator_fab(*dargs, **dkwargs):
            return make_decorator(deco, dargs, dkwargs)
        return wraps(deco)(decorator_fab)


def has_1pos_and_kwonly(func):
    """Check if function has exactly 1 positional arg and only keyword-only args."""
    if PY2:
        spec = inspect.getfullargspec(func) if hasattr(inspect, 'getfullargspec') else inspect.getargspec(func)
        # In Python 2, we can't really check kwonlyargs easily, but let's try
        if hasattr(spec, 'kwonlyargs'):
            return len(spec.args) == 1 and not spec.varargs and not spec.keywords
        return False
    else:
        spec = inspect.signature(func)
        pos_count = 0
        for param in spec.parameters.values():
            if param.kind in (inspect.Parameter.POSITIONAL_ONLY, 
                              inspect.Parameter.POSITIONAL_OR_KEYWORD):
                pos_count += 1
            elif param.kind == inspect.Parameter.KEYWORD_ONLY:
                continue  # keyword-only args are OK
            else:
                return False  # VAR_POSITIONAL or VAR_KEYWORD not allowed
        return pos_count == 1


def make_decorator_kwonly(deco):
    """Create a decorator factory for functions with 1 positional + kwonly args."""
    spec = inspect.signature(deco)
    params = list(spec.parameters.values())

    # First param is 'call' (positional), rest are keyword-only with defaults
    kwonly_params = {}
    for param in params[1:]:
        if param.kind == inspect.Parameter.KEYWORD_ONLY:
            if param.default is inspect.Parameter.empty:
                raise TypeError("Keyword-only argument without default is not supported")
            kwonly_params[param.name] = param.default

    @wraps(deco)
    def _decorator(func=None, /, **kwds):
        if func is None:
            # Called with arguments: @decorator(arg=val)
            # Return a new decorator with those kwargs
            merged = {**kwonly_params, **kwds}
            return make_decorator_kwonly_impl(deco, merged)
        else:
            # Called directly: @decorator
            return make_decorator_kwonly_impl(deco, kwonly_params)

    _decorator._func = deco
    return _decorator


def make_decorator_kwonly_impl(deco, dkwargs):
    """Internal implementation for making a decorator with specific kwargs."""
    @wraps(deco)
    def _decorator(func):
        def wrapper(*args, **kwargs):
            call = Call(func, args, kwargs)
            return deco(call, *dkwargs.values())
        return wraps(func)(wrapper)

    _decorator._func = deco
    _decorator._args = ()
    _decorator._kwargs = dkwargs
    return _decorator


